# -*- coding: utf-8 -*-
"""
Generates 150 distinct MCQs for Topic 4: Quy luật Di truyền & Bản đồ Gen (mendel).
Targets: 52 basic (7 orig + 45 new), 53 adv (7 orig + 46 new), 45 hsg (8 orig + 37 new).
"""
import json
from common import SCRIPTS_DIR, make_mcq, validate_question_list, write_js_module


def build_mendel_mcqs():
    orig_all = json.loads((SCRIPTS_DIR / "original_132.json").read_text(encoding="utf-8"))
    orig = [x for x in orig_all if x["topic"] == "mendel"]

    items = []
    idx = 1

    def add(level, subtopic, q, opts, ans, exp):
        nonlocal idx
        qid = f"MCQ-MD-{idx:03d}"
        items.append(make_mcq(qid, "mendel", level, subtopic, q, opts, ans, exp))
        idx += 1

